        String // \"ACB\" | \"MCCB\" | \"MCB\" | \"RCCB\" | \"RCBO\" | \"SPD\" | \"CONTACTOR\" | \"OVERLOAD\" | \"METER\" | \"CT\"\n  manufacturer     String // \"ABB\" | \"SCHNEIDER\"\n  series           String // e.g. \"Emax 2\", \"Tmax XT4\", \"Acti9 iC60\"\n  model            String // e.g. \"E2.2B 1600\"\n  ratedCurrent     Float // nominal current rating (In) in A\n  poles            Int            @default(3)\n  breakingCapacity Float // Icu in kA\n  tripUnit         String? // e.g. \"Ekip Dip LSI\", \"MicroLogic 2.2\"\n  settingsJson     String? // JSON string: adjustable protection settings ranges\n  datasheetUrl     String?\n  familyId         String?\n  family           BreakerFamily? @relation(fields: [familyId], references: [id], onDelete: SetNull)\n\n  @@unique([manufacturer, category, series, model, ratedCurrent, poles], name: \"catalogUniqueKey\")\n  @@index([familyId])\n}\n\nmodel BreakerFamily {\n  id           String             @id @default(uuid())\n  manufacturer String // e.g. \"ABB\" | \"Schneider\"\n  category     String // \"ACB\" | \"MCCB\" | \"MCB\"\n  name         String // e.g. \"ComPacT NSX\", \"Acti9 iC60\"\n  catalogItems EquipmentCatalog[]\n  defaultAcb   Project[]          @relation(\"DefaultAcbFamily\")\n  defaultMccb  Project[]          @relation(\"DefaultMccbFamily\")\n  defaultMcb   Project[]          @relation(\"DefaultMcbFamily\")\n  createdAt    DateTime           @default(now())\n  updatedAt    DateTime           @updatedAt\n\n  @@unique([manufacturer, category, name])\n}\n\nmodel BreakerSettings {\n  id           String   @id @default(uuid())\n  breakerId    String   @unique // The unique tag of the feeder in the design (e.g. \"proj1-mdb-main\")\n  model        String\n  manufacturer String\n  frameSize    String\n  ir           Float // L pickup setting\n  tr           Float // L delay setting\n  isd          Float? // S pickup setting\n  tsd          Float? // S delay setting\n  i2t          Boolean? // S I2t state (on/of